import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.AbstractQueuedSynchronizer;
import java.util.concurrent.locks.Condition;

public class Main {
    static final class Mutex {
        private final Sync sync = new Sync();

        private static final class Sync extends AbstractQueuedSynchronizer {
            @Override
            protected boolean tryAcquire(int arg) {
                if (compareAndSetState(0, 1)) {
                    setExclusiveOwnerThread(Thread.currentThread());
                    return true;
                }
                return false;
            }

            @Override
            protected boolean tryRelease(int arg) {
                if (getState() == 0 || getExclusiveOwnerThread() != Thread.currentThread()) {
                    throw new IllegalMonitorStateException();
                }
                setExclusiveOwnerThread(null);
                setState(0);
                return true;
            }

            @Override
            protected boolean isHeldExclusively() {
                return getState() == 1 && getExclusiveOwnerThread() == Thread.currentThread();
            }

            Condition newCondition() {
                return new ConditionObject();
            }
        }

        void lock() { sync.acquire(1); }
        void unlock() { sync.release(1); }
        Condition newCondition() { return sync.newCondition(); }
    }

    static final class OneShotLatch {
        private final Sync sync = new Sync();

        private static final class Sync extends AbstractQueuedSynchronizer {
            @Override
            protected int tryAcquireShared(int arg) {
                return getState() == 1 ? 1 : -1;
            }

            @Override
            protected boolean tryReleaseShared(int arg) {
                setState(1);
                return true;
            }
        }

        void await() throws InterruptedException { sync.acquireSharedInterruptibly(1); }
        void signal() { sync.releaseShared(1); }
    }

    public static void main(String[] args) throws Exception {
        Mutex mutex = new Mutex();
        int threads = 4;
        int rounds = 20_000;
        int[] counter = {0};
        CountDownLatch done = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                for (int j = 0; j < rounds; j++) {
                    mutex.lock();
                    try {
                        counter[0]++;
                    } finally {
                        mutex.unlock();
                    }
                }
                done.countDown();
            }, "mutex-worker-" + i).start();
        }
        done.await();
        System.out.println("mutex counter=" + counter[0]);
        assert counter[0] == threads * rounds;

        Condition condition = mutex.newCondition();
        boolean[] ready = {false};
        Thread waiter = new Thread(() -> {
            mutex.lock();
            try {
                while (!ready[0]) {
                    condition.awaitUninterruptibly();
                }
                System.out.println("condition awakened");
            } finally {
                mutex.unlock();
            }
        }, "condition-waiter");
        waiter.start();
        Thread.sleep(100);
        mutex.lock();
        try {
            ready[0] = true;
            condition.signal();
        } finally {
            mutex.unlock();
        }
        waiter.join();

        OneShotLatch latch = new OneShotLatch();
        AtomicInteger passed = new AtomicInteger();
        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                try {
                    latch.await();
                    passed.incrementAndGet();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }, "latch-waiter-" + i).start();
        }
        Thread.sleep(100);
        latch.signal();
        Thread.sleep(100);
        System.out.println("latch passed=" + passed.get());
        assert passed.get() == 3;
    }
}
